// AccessExplanation defines model for AccessExplanation.
type AccessExplanation struct {
	// Groups Their groups of the identity provider, at their last sign-in.
	Groups []string `json:"groups"`

	// Permissions Every permission of the catalogue, in its order, then the day-2 permissions held.
	Permissions []AccessPermission `json:"permissions"`

	// Project The project asked about; null for all of rvav.
	Project *ProjectRef `json:"project"`

	// Roles The roles that count here, those given for all of rvav included.
	Roles []AccessGrant `json:"roles"`
	User  UserRef       `json:"user"`
}

// AccessGrant A role a user holds, and where it comes from.
type AccessGrant struct {
	// Given Given in the project, or for all of rvav.
	Given AccessGrantGiven `json:"given"`

	// Group The group of the identity provider, when through one.
	Group *string `json:"group,omitempty"`
	Role  RoleRef `json:"role"`

	// Through `user`: given to them; `group`: through a group mapping; `rvav`:
	// set by rvav itself (`user` for everyone signed in, the local
	// administrator's, the system users' and the seed's).
	Through AccessGrantThrough `json:"through"`
}

// AccessGrantGiven Given in the project, or for all of rvav.
type AccessGrantGiven string

// AccessGrantThrough `user`: given to them; `group`: through a group mapping; `rvav`:
// set by rvav itself (`user` for everyone signed in, the local
// administrator's, the system users' and the seed's).
type AccessGrantThrough string

// AccessPermission defines model for AccessPermission.
type AccessPermission struct {
	// GrantedBy The roles granting it here; empty when none does. `approval.project`
	// counts from a role given in the project only.
	GrantedBy []AccessGrant `json:"granted_by"`
	Held      bool          `json:"held"`

	// Id A permission's stable identifier: one of the catalogue (`project.see`,
	// `policies.manage`), or a day-2 one, `day2.<group>` or
	// `day2.<group>:<action>`.
	//
	//
	// Examples: project.see, day2.power:power_on
	Id Permission `json:"id"`
}

